{
  "a_sentences": [
    {
      "a_text": "Le bail de durée indéterminée peut être résilié pour la prochaine échéance en respectant le délai de congé prévu (art. 266a al. 1 CO), le bailleur étant libre d'adapter l'exploitation de son bien, de réaliser des travaux, de poursuivre des motifs économiques ou d'utiliser les locaux pour lui-même ou ses proches (P1, P2).",
      "b_propositions": ["P1", "P2"]
    },
    {
      "a_text": "Un congé ordinaire contrevient aux règles de la bonne foi s'il ne répond à aucun intérêt objectif, sérieux et digne de protection, s'il est purement chicanier, s'il repose sur un prétexte, si la motivation est lacunaire ou fausse, ou s'il crée une disproportion grossière entre les intérêts en présence (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Pour examiner la validité du congé, il faut déterminer le motif invoqué par le bailleur au moment de la résiliation et se placer à ce moment précis (P4, P5).",
      "b_propositions": ["P4", "P5"]
    },
    {
      "a_text": "Le juge peut prendre en compte la durée de la procédure judiciaire qui prolonge de fait le bail (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que le souhait de l'intimée de ne plus être liée contractuellement au recourant apparaissait légitime (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que la solution cantonale ne viole pas le droit fédéral (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
